import{_ as d,o,c,a0 as t}from"./chunks/framework.Bb-2yHh0.js";const P=JSON.parse('{"title":"附录 A PC 硬件","description":"","frontmatter":{"title":"附录 A PC 硬件","outline":[2,3]},"headers":[],"relativePath":"appA.md","filePath":"appA.md"}'),a={name:"appA.md"};function p(r,e,s,i,n,l){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="附录-a-pc-硬件" tabindex="-1">附录 A　PC 硬件 <a class="header-anchor" href="#附录-a-pc-硬件" aria-label="Permalink to &quot;附录 A　PC 硬件&quot;">​</a></h1><p>本附录描述个人计算机（PC）硬件，即 xv6 运行的平台。</p><p>PC 是遵循若干行业标准的计算机，其目标是让某一份软件能够在多个厂商销售的 PC 上运行。这些标准随时间演进，1990 年代的 PC 与今天的 PC 看起来并不相同。当前的许多标准是公开的，你可以在网上找到它们的文档。</p><p>从外部看，PC 是一个带键盘、屏幕和各种设备（例如 CD-ROM 等）的箱子。箱子内部是一块电路板（“主板”），上面有 CPU 芯片、内存芯片、图形芯片、I/O 控制器芯片，以及芯片之间通信的总线。总线遵循标准协议（例如 PCI 和 USB），使设备能够与多个厂商的 PC 配合工作。</p><p>从我们的角度看，可以把 PC 抽象为三个组成部分：CPU、内存和输入/输出（I/O）设备。CPU 执行计算，内存包含用于该计算的指令和数据，设备则使 CPU 能够与用于存储、通信和其他功能的硬件交互。</p><p>你可以把主存想象成通过一组导线（或称线路）与 CPU 相连，其中一些用于地址位，一些用于数据位，还有一些用于控制标志。要从主存读取一个值，CPU 在地址线上发送表示 1 或 0 位的高电压或低电压，并在“读”线上发送 1，持续一段规定的时间，然后通过解释数据线上的电压读回该值。要向主存写入一个值，CPU 在地址线和数据线上发送相应的位，并在“写”线上发送 1，持续一段规定的时间。真实的内存接口比这更复杂，但只有在你需要达到高性能时，这些细节才重要。</p><h2 id="appA-s1" tabindex="-1">处理器与内存 <a class="header-anchor" href="#appA-s1" aria-label="Permalink to &quot;处理器与内存 {#appA-s1}&quot;">​</a></h2><p>计算机的 CPU（中央处理器，或处理器）运行一个概念上很简单的循环：它查看一个称为<em>程序计数器</em>的寄存器中的地址，从内存中该地址处读取一条机器指令，把程序计数器推进到该指令之后，然后执行该指令。重复。如果指令的执行没有修改程序计数器，这个循环就会把程序计数器所指的内存解释为一串依次运行的机器指令。确实会改变程序计数器的指令包括分支和函数调用。</p><p>如果没有存储和修改程序数据的能力，执行引擎就毫无用处。最快的数据存储由处理器的寄存器组提供。寄存器是处理器内部的一个存储单元，能够保存一个机器字大小的值（通常是 16、32 或 64 位）。存放在寄存器中的数据通常可以在一个 CPU 周期内快速读取或写入。</p><p>PC 的处理器实现 x86 指令集，该指令集最初由 Intel 定义，现已成为标准。多家制造商生产实现该指令集的处理器。与所有其他 PC 标准一样，这个标准也在演进，但较新的标准向后兼容过去的标准。引导加载器必须应对其中一部分演进，因为每个 PC 处理器启动时都模拟 Intel 8088，即 1981 年发布的原始 IBM PC 中的 CPU 芯片。不过，xv6 的大部分内容只涉及现代 x86 指令集。</p><p>现代 x86 提供八个通用 32 位寄存器——<code>%eax</code>、<code>%ebx</code>、<code>%ecx</code>、<code>%edx</code>、<code>%edi</code>、<code>%esi</code>、<code>%ebp</code> 和 <code>%esp</code>——以及一个程序计数器 <code>%eip</code>（<em>指令指针</em>）。共同的前缀代表 extended（扩展），因为它们是 16 位寄存器 <code>%ax</code>、<code>%bx</code>、<code>%cx</code>、<code>%dx</code>、<code>%di</code>、<code>%si</code>、<code>%bp</code>、<code>%sp</code> 和 <code>%ip</code> 的 32 位扩展。这两组寄存器是互为别名的，因此举例来说，<code>%ax</code> 是 <code>%eax</code> 的低半部分：写入 <code>%ax</code> 会改变 <code>%eax</code> 中存储的值，反之亦然。前四个寄存器还为其低端的两个 8 位字节提供了名字：<code>%al</code> 和 <code>%ah</code> 分别表示 <code>%ax</code> 的低 8 位和高 8 位；<code>%bl</code>、<code>%bh</code>、<code>%cl</code>、<code>%ch</code>、<code>%dl</code> 和 <code>%dh</code> 沿用同样的模式。除了这些寄存器，x86 还有八个 80 位浮点寄存器，以及少量专用寄存器，例如<em>控制寄存器</em> <code>%cr0</code>、<code>%cr2</code>、<code>%cr3</code> 和 <code>%cr4</code>；调试寄存器 <code>%dr0</code>、<code>%dr1</code>、<code>%dr2</code> 和 <code>%dr3</code>；<em>段寄存器</em> <code>%cs</code>、<code>%ds</code>、<code>%es</code>、<code>%fs</code>、<code>%gs</code> 和 <code>%ss</code>；以及全局和局部描述符表的伪寄存器 <code>%gdtr</code> 和 <code>%ldtr</code>。控制寄存器和段寄存器对任何操作系统都很重要。浮点和调试寄存器则不那么有趣，xv6 也不使用它们。</p><p>寄存器很快但很昂贵。大多数处理器至多提供几十个通用寄存器。下一个概念层次的存储是主随机访问存储器（RAM）。主存比寄存器慢 10–100 倍，但便宜得多，因此可以有很多。主存相对较慢的一个原因是它在物理上与处理器芯片分离。x86 处理器有几十个寄存器，但今天典型的 PC 有数十亿字节的主存。由于寄存器与主存在访问速度和容量上都存在巨大差异，大多数处理器（包括 x86）会在片上缓存存储器中保存最近访问过的部分主存的副本。缓存存储器在访问时间和容量上都充当寄存器与内存之间的中间地带。今天的 x86 处理器通常有三层缓存。每个核有一个小的第一层缓存，其访问时间相对接近处理器的时钟频率，还有一个更大的第二层缓存。若干核共享一个 L3 缓存。<a class="figref" href="#fig-xeon">图 A-1</a> 展示了 Intel i7 Xeon 处理器内存层次中的各层及其访问时间。</p><figure class="xv6-fig xv6-table" id="fig-xeon"><table><thead><tr><th>存储器</th><th>访问时间</th><th>容量</th></tr></thead><tbody><tr><td>寄存器</td><td>1 个周期</td><td>64 字节</td></tr><tr><td>L1 缓存</td><td>约 4 个周期</td><td>64 KB</td></tr><tr><td>L2 缓存</td><td>约 10 个周期</td><td>4 MB</td></tr><tr><td>L3 缓存</td><td>约 40–75 个周期</td><td>8 MB</td></tr><tr><td>远程 L3</td><td>约 100–300 个周期</td></tr><tr><td>本地 DRAM</td><td>约 60 纳秒</td></tr><tr><td>远程 DRAM</td><td>约 100 纳秒</td></tr></tbody></table><figcaption><span class="fig-no">图 A-1</span>Intel i7 Xeon 系统的延迟数据，基于 http://software.intel.com/sites/products/collateral/hpc/vtune/performance_analysis_guide.pdf。</figcaption></figure><p>在很大程度上，x86 处理器对操作系统隐藏了缓存，因此我们可以认为处理器只有两种存储——寄存器和内存——而不必担心内存层次中不同层级之间的区别。</p><h2 id="appA-s2" tabindex="-1">I/O <a class="header-anchor" href="#appA-s2" aria-label="Permalink to &quot;I/O {#appA-s2}&quot;">​</a></h2><p>处理器必须与设备通信，也必须与内存通信。x86 处理器提供特殊的 <code>in</code> 和 <code>out</code> 指令，用于从称为 <em>I/O 端口</em>的设备地址读取值或向其写入值。这些指令的硬件实现本质上与读写内存相同。早期的 x86 处理器多了一条地址线：0 表示从 I/O 端口读写，1 表示从主存读写。每个硬件设备都会监视这些线，以捕捉对其所分配 I/O 端口范围的读写。设备的端口让软件能够配置设备、检查其状态，并促使设备采取动作；例如，软件可以用 I/O 端口读写来促使磁盘接口硬件在磁盘上读写扇区。</p><p>许多计算机体系结构没有单独的设备访问指令。取而代之的是，设备具有固定的内存地址，处理器（在操作系统的授意下）通过读写这些地址处的值与设备通信。事实上，现代 x86 体系结构对大多数高速设备（例如网络、磁盘和图形控制器）都使用这种称为<em>内存映射 I/O</em> 的技术。不过，为了向后兼容，旧的 <code>in</code> 和 <code>out</code> 指令仍然存在，使用它们的旧式硬件设备也仍然存在，例如 xv6 所使用的 IDE 磁盘控制器。</p>',17)])])}const h=d(a,[["render",p]]);export{P as __pageData,h as default};
